      SUBROUTINE INQCC     MATRIX INVERSION TO SOLVE NORMAL EQUATIONS FOR FITTINGCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10D.CIN'CC     LOCAL VARIABLESC      INTEGER  ROW(NPVAR+1), COL(NPVAR+1)      REAL     CAT(NPVAR+1)CC------------------------------------------------------------------------CC     CALCULATE SCALING FACTOR FOR NORMAL MATRIXC      N = NV1 + 1      SCALE(1) = 1.0      DO 135 J = 2, N      SCALE(J) = 0.0      IF (CA(J,J) .NE. 0.0) SCALE(J) = 1.0/SQRT(ABS(CA(J,J)))  135 CONTINUECC     NORMALIZE ROWS AND COLUMNSC      DO 15 I = 2, N      DO 15 J = 1, N      CA(I,J) = CA(I,J)*SCALE(I)*SCALE(J)   15 CONTINUE      CM0 = 1.0E-5CC     ADD MARQUARDT-LEVENBERG PARAMETERC      IF (NMAR .GT. 0) THEN        PMARQ = PARQ*(2.0**NMAR - 1.0)        IF (PMARQ .GT. 0.0) THEN          DO 18 J = 2, N   18     CA(J,J) = CA(J,J) + PMARQ        ENDIF      ELSE        PMARQ = 0.0      ENDIFCC     INVERT SIGNIFICANT PORTION OF MATRIXC   20 DO 100 KK = 2, N      K = KKCC     FIND ROW WITH LARGEST REMAINING DIFFERENCEC      CM  =  -1.      DO 25 I = K, N      CM1 = ABS(CA(I,1))      IF (CM1 .GT. CM) THEN        CM = CM1        KI = I      ENDIF   25 CONTINUECC     FIND COLUMN WITH LARGEST ELEMENT IN PREVIOUSLY DETERMINED ROWC      CM  =  -1.      DO 30 J = K, N      I = KI      CM1 = ABS(CA(I,J))      IF (CM1 .GT. CM) THEN        CM = CM1        KJ = J      ENDIF   30 CONTINUECC     IS FOUND ELEMENT LARGE ENOUGHC      IF (CM .GE. CM0) GO TO 60CC     IF NOT FIND LARGEST REMAINING ELEMENT IN MATRIXC      CM  =  -1.      DO 40 I = K, N      DO 40 J = K, N      CM1 = ABS(CA(I,J))      IF (CM1 .GT. CM) THEN        CM = CM1        KI = I        KJ = J      ENDIF   40 CONTINUECC     IS FOUND ELEMENT LARGE ENOUGHC      IF (CM .GE. CM0) GO TO 60CC     IF NOT, ZERO REMAINING MATRIXC   45 KP = K      K = K - 1      DO 50 I = KP, N      DO 50 J = 1, N      CA(I,J) = 0.0      CA(J,I) = 0.0   50 CONTINUE      GO TO 110CC     SWITCH AND RENORMALIZE ROWSC   60 ROW(K) = KI      COL(K) = KJ      CK = 1./CA(KI,KJ)      CA(KI,KJ) = - CA(KI,KJ)      DO 70 J = 1, N, 1      CAT(J) = CA(KI,J)      CA(KI,J) = CA(K,J)      CA(K,J) = CK*CAT(J)   70 CONTINUE      CAT(KJ) = CAT(K)      DO 80 I = 2, N      CK1 = - CK * CA(I,KJ)      CA(I,KJ) = CA(I,K)      CA(I,K) = CK1      IF (I .NE. K) THEN        DO 75 J = 1, N        IF (J .NE. K) CA(I,J) = CA(I,J) + CK1*CAT(J)   75   CONTINUE      ENDIF   80 CONTINUE  100 CONTINUECC     RELOCATE ROWS AND COLUMNSC  110 IF (K .LT. 2) GO TO 150      KI = COL(K)      DO 120 J = 1, N, 1      CK = CA(K,J)      CA(K,J) = CA(KI,J)      CA(KI,J) = CK  120 CONTINUE      KJ = ROW(K)      DO 130 I = 2, N      CK = CA(I,K)      CA(I,K) = CA(I,KJ)      CA(I,KJ) = CK  130 CONTINUE      K = K - 1      GO TO 110  150 CONTINUECC     CALCULATE MARQUARDT-LEVENBERG PARAMETERC      IF (PMARQ .NE. 0.0) GO TO 160      DO 154 I = 2, N      SUM = 0.0      DO 152 J = 2, N      SUM = SUM + CA(I,J)*CA(J,1)  152 CONTINUE      CAT(I) = SUM  154 CONTINUE      DNUM = 0.0      DEN = 0.0      DO 155 J = 2, N      DNUM = DNUM + CA(J,1)*CA(J,1)      DEN = DEN + CAT(J)*CAT(J)  155 CONTINUE      IF (DEN .NE. 0.0) THEN        PARQ = SQRT(DNUM/DEN)      ELSE        PARQ = 0.0      ENDIFCC     RENORMALIZE INVERTED MATRIXC  160 DO 170 I = 2, N      DO 170 J = 1, N  170 CA(I,J) = CA(I,J)*SCALE(I)*SCALE(J)C      RETURN      END